#!/usr/bin/env bash
# Formal opt-in capability: exact normal and failure-atomicity targets.
set -euo pipefail
mode="${1:-}"
[[ $# -le 1 && ( "$mode" == '' || "$mode" == --list-only ) ]] || { echo 'usage: check_e2_two_source_unit_ci.sh [--list-only]' >&2; exit 2; }
if [[ "$mode" != --list-only ]]; then
  [[ "${CI:-}" == true && "${GITHUB_ACTIONS:-}" == true ]] || { echo 'Two-source Unit faults require CI; use --list-only locally' >&2; exit 2; }
fi
cd "$(dirname "$0")/.."
for features in two-source-unit 'two-source-unit e2-two-source-test-support loan-observation-test-support'; do
  for name in early_temp_shared::early_temp_shared_original_facts_preserve_first_temporary early_temp_shared::early_temp_shared_closed_facts_prepare_asymmetric_lifetime early_temp_shared::early_temp_shared_rejects_uncovered_shapes late_temp_shared::late_temp_shared_original_facts_preserve_second_temporary late_temp_shared::late_temp_shared_closed_facts_prepare_asymmetric_lifetime late_temp_shared::late_temp_shared_rejects_reverse_and_uncovered_shapes joint_final_distinct::joint_final_distinct_original_facts_preserve_joint_last_use joint_final_distinct::joint_final_distinct_closed_facts_prepare_joint_retirement joint_final_distinct::joint_final_distinct_rejects_other_shapes_and_unclaimed_shells joint_final_named::joint_final_named_original_facts_preserve_joint_last_use joint_final_named::joint_final_named_closed_facts_prepare_joint_retirement joint_final_named::joint_final_named_rejects_outside_bounded_domain late_distinct::late_distinct_original_facts_keep_formation_between_calls late_distinct::late_distinct_closed_facts_prepare_late_owner late_distinct::late_distinct_rejects_other_shapes_and_unclaimed_shells staggered_distinct::staggered_distinct_original_facts_preserve_separate_last_use staggered_distinct::staggered_distinct_closed_facts_prepare_two_owner_root staggered_distinct::staggered_distinct_rejects_other_shapes_and_unclaimed_shells shared_mixed_distinct::shared_mixed_distinct_original_facts_preserve_interleaved_cleanup shared_mixed_distinct::shared_mixed_distinct_closed_facts_prepare_interleaved_root shared_mixed_distinct::shared_mixed_distinct_reject_other_shapes_and_unclaimed_shells shared_distinct_callees::shared_distinct_callees_original_facts_preserve_one_final_owner_drop shared_distinct_callees::shared_distinct_callees_closed_facts_prepare_shared_root shared_distinct_callees::shared_distinct_callees_reject_other_shapes_and_unclaimed_shells distinct_callees::distinct_callees_preserve_original_instances_and_call_lifetimes distinct_callees::distinct_callees_keep_other_lifetime_and_shape_boundaries distinct_callees::distinct_callees_reject_unclosed_and_unclaimed_definitions occurrence_bindings::occurrence_bindings_preserve_pure_multi_entry_mapping occurrence_bindings::occurrence_bindings_keep_single_callee_and_repeated_occurrences occurrence_bindings::occurrence_bindings_reject_computed_scalar_with_named_distinct_callees occurrence_bindings::occurrence_bindings_distinct_callers_keep_original_temporary_cleanup late_initialization::late_initialization_original_facts_keep_formation_between_calls late_initialization::late_initialization_emits_after_first_cleanup_before_second_acquisition late_initialization::late_initialization_rejects_other_formation_and_call_shapes scalar_origin::scalar_literal_loans_supply_original_observed_direct_call_ends direct_scalars::direct_scalar_arguments_preserve_real_constants_and_cleanup direct_scalars::direct_scalar_arguments_keep_restricted_expression_boundary direct_scalars::direct_scalars_do_not_leave_unused_locals_or_accept_boolean_expressions expression_entry::expression_entry_original_call_finishes_all_loans_and_string_owners expression_entry::expression_entry_lowers_only_the_original_direct_call two_call_entry::two_call_entry_original_facts_keep_call_local_cleanup two_call_entry::two_call_entry_finishes_first_lifetime_before_second_acquisition two_call_entry::two_call_entry_preserves_second_named_argument_order_and_values two_call_entry::two_call_entry_rejects_distinct_callees_with_computed_scalar two_call_entry::two_call_entry_rejects_uncovered_statements_and_shared_named_lifetimes shared_owner_pair::shared_owner_pair_original_facts_keep_owner_until_last_call shared_owner_pair::shared_owner_pair_emits_one_owner_across_two_complete_lifetimes shared_owner_pair::shared_owner_pair_rejects_other_lifetime_shapes shared_mixed_pair::shared_mixed_pair_original_facts_order_temporary_before_final_named_drop shared_mixed_pair::shared_mixed_pair_replays_interleaved_owner_lifetimes shared_mixed_pair::shared_mixed_pair_rejects_asymmetric_or_uncovered_lifetimes staggered_owners::staggered_owners_original_facts_observe_each_roots_last_call staggered_owners::staggered_owners_emit_distinct_initializations_and_original_last_use_drops staggered_owners::staggered_owners_reject_other_root_and_call_shapes integer_literals::entry_integer_spellings_preserve_value_and_source_span integer_literals::entry_integer_spellings_keep_expression_and_type_boundaries named_arguments::named_arguments_preserve_source_borrows_and_signature_delivery parameter_roles::entry_arguments_preserve_all_signature_role_permutations parameter_roles::entry_role_permutations_reject_grouped_scalar_arguments declaration_order::entry_declarations_preserve_source_order_and_scalar_roles declaration_order::entry_declaration_permutations_do_not_admit_extra_or_computed_locals static_strings::static_string_escapes_preserve_bytes_in_every_owner_shape static_strings::static_string_entries_still_reject_real_interpolation explicit_capability_checks_whole_unit_and_source_identity explicit_capability_executes_original_object explicit_capability_commit_failure_is_atomic multiple_entries_preserve_complete_selection_and_mapping multiple_entries_commit_failure_is_atomic multiple_entries_reject_unsupported_entry shared_entries::shared_caller_entries_use_exact_fact_set_and_independent_roots named_shared_owner_entry_is_closed_and_unique distinct_named::distinct_named_owners_preserve_argument_identity_and_cleanup mixed_owner::mixed_owner_entry_preserves_temporary_argument_and_named_cleanup validation_errors::ownership_validation_errors_are_not_unsupported_selection validation_errors::deferred_rejection_is_distinct_from_valid_unsupported_subset combined_entries::named_shared_entries_keep_cleanup_and_whole_unit_diagnostics; do
    target="ssa::two_source_unit::tests::$name"
    args=(--exact)
    [[ "$name" != *_commit_failure_is_atomic ]] || args+=(--ignored)
    listing=$(cargo test --locked -j1 -p lang-codegen --lib --features "$features" "$target" -- "${args[@]}" --list)
    [[ $(grep -Fxc "$target: test" <<< "$listing") == 1 ]]
    if [[ "$mode" != --list-only ]]; then
      cargo test --locked -j1 -p lang-codegen --lib --features "$features" "$target" -- "${args[@]}"
    fi
  done
  for public in public_capability_emits_and_executes_without_test_observers public_multiple_entries_execute_one_common_program public_named_shared_owner_executes_exact_source public_distinct_named_owners_execute_reversed_arguments public_mixed_owner_entry_executes_temporary_first public_shared_caller_entries_execute_distinct_roots public_shared_named_entries_execute_distinct_owners; do
    listing=$(cargo test --locked -j1 -p lang-codegen --test two_source_unit --features "$features" "$public" -- --exact --list)
    [[ $(grep -Fxc "$public: test" <<< "$listing") == 1 ]]
    if [[ "$mode" != --list-only ]]; then
      cargo test --locked -j1 -p lang-codegen --test two_source_unit --features "$features" "$public" -- --exact
    fi
  done
done
frontend=ownership_checking::compilation_unit::loop_no_carry::two_source_candidate::tests::named_shared_string_entry_cleanup_evidence
listing=$(cargo test --locked -j1 -p lang-frontend --lib --features 'e2-two-source-test-support loan-observation-test-support' "$frontend" -- --exact --list)
[[ $(grep -Fxc "$frontend: test" <<< "$listing") == 1 ]]
if [[ "$mode" != --list-only ]]; then
  cargo test --locked -j1 -p lang-frontend --lib --features 'e2-two-source-test-support loan-observation-test-support' "$frontend" -- --exact
fi
if [[ "$mode" == --list-only ]]; then
  echo 'Two-source Unit: 76 unit and 7 public-library targets in 2 configurations plus 1 frontend evidence target listed; none executed'
fi
